cd /private/tmp/100-tricks-runs/d06/without/h2-eval-thresholds/r2 && cat > /tmp/test-threshold.mjs << 'EOF'
import { runEvaluations, generateReport } from './packages/frai-core/src/eval/index.js';
import { toMarkdown, toJson } from './packages/frai-core/src/eval/reporters.js';

// Test 1: Passing thresholds
const evaluations = runEvaluations({
  outputs: ['Hello', 'World'],
  references: ['hello', 'world']
});

const reportPass = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5 }
});

console.log('=== PASSING THRESHOLDS REPORT ===');
console.log('JSON:');
console.log(JSON.stringify(reportPass, null, 2));
console.log('\nMarkdown:');
console.log(toMarkdown(reportPass));

// Test 2: Failing thresholds
const reportFail = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.99 }
});

console.log('\n=== FAILING THRESHOLDS REPORT ===');
console.log('JSON:');
console.log(JSON.stringify(reportFail, null, 2));
console.log('\nMarkdown:');
console.log(toMarkdown(reportFail));

// Test 3: No thresholds
const reportNoThresh = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});

console.log('\n=== NO THRESHOLDS REPORT ===');
console.log('JSON (should not have passed/thresholds):');
console.log(JSON.stringify(reportNoThresh, null, 2));
EOF
node /tmp/test-threshold.mjs
